using System;
using Cysharp.Threading.Tasks;
using UnityEngine;
using UnityEngine.AddressableAssets;

namespace XFramework
{
    /// <summary>
    /// 游戏总管理器
    /// </summary>
    public class GameManager : MonoOdinSingleton<GameManager>
    {
        [Header("资源加载")]
        [Tooltip("编辑器下默认使用本地资源；切到 Addressables 可以预览真实 Addressables 加载链路。打包后始终使用 Addressables。")]
        [SerializeField] 
        private AssetsLoadMode assetsLoadMode = AssetsLoadMode.LocalAssetDatabase;

        public CommonUI _commonUI;

        /// <summary>
        /// 游戏开始事件
        /// </summary>
        public  event Action OnEnterGame;
        /// <summary>
        /// 游戏结束事件
        /// </summary>
        public event Action OnExitGame;

        protected override void Awake()
        {
            base.Awake();
            DontDestroyOnLoad(gameObject);
            AssetsManager.Instance.SetLoadMode(assetsLoadMode);
            LanguageManager.Instance.Initialized().Forget();
            ResolutionManager.Instance.Initialized().Forget();
        }

        private void Start()
        {
            Initialized().Forget();
        }

        public async UniTask Initialized()
        {
            await Addressables.InitializeAsync();
            await PlayerInputManager.Instance.Initialized();
            await AudioManager.Instance.Initialized();
            await UISystem.Instance.Initialized();
            await SaveGameManager.Instance.Initialized();
            await InventoryManager.Instance.Initialized();

            Application.targetFrameRate = -1;
            StarGame();
        }

        private void StarGame()
        {
            _commonUI.Open();
            _commonUI.Init();
        }

        public void EnterGame(UserSaveSummary selectedUserSaveSummary)
        {
            UISystem.Instance.CloseUI("CommonUI");
            OnEnterGame?.Invoke();
            UISystem.Instance.OpenUI<MainUI>("MainUI");
        }

        protected virtual void OnOnExitGame()
        {
            OnExitGame?.Invoke();
        }
    }
}

using System;
using System.Collections.Generic;
using Cysharp.Threading.Tasks;
using PathologicalGames;
using Sirenix.OdinInspector;
using UnityEngine;
using UnityEngine.Audio;

namespace XFramework
{
    /// <summary>
    /// 音效总管理器
    /// </summary>
    public class AudioManager : MonoOdinSingleton<AudioManager>,IGameInitialized
    {
        #region IGameInitialized

        [BoxGroup("Initialized"),LabelText("配置路径"),FilePath]
        public string ConfigPath = "Assets/AddressableAssets/Configs/UIPage/PageConfiguration.asset";
        [BoxGroup("Initialized"),ShowInInspector,LabelText("配置表数据"),ReadOnly]
        private AudioConfiguration _audioConfiguration;

        public async UniTask Initialized()
        {
            _audioConfiguration = await AssetsManager.Instance.
                    LoadAssetsUniTask<AudioConfiguration>(ConfigPath);
            InitializedComplete();
            InitializedSnapshot();
            await InitializedMusicSource();
        }

        private void InitializedComplete()
        {
            XMixer = _audioConfiguration.XMixer;
            bgmSource = transform.Find("BgmSource").GetComponent<AudioSource>();
            ambientSource = transform.Find("AmbientSource").GetComponent<AudioSource>();
            humanSource = transform.Find("HumanSource").GetComponent<AudioSource>();
            videoSource = transform.Find("VideoSource").GetComponent<AudioSource>();

            bgmSource.outputAudioMixerGroup =  _audioConfiguration.GetByMixerGroup(AudioMixerGroupType.BGMItem);
            ambientSource.outputAudioMixerGroup =  _audioConfiguration.GetByMixerGroup(AudioMixerGroupType.AmbientItem);
            humanSource.outputAudioMixerGroup =  _audioConfiguration.GetByMixerGroup(AudioMixerGroupType.HumanItem);
            videoSource.outputAudioMixerGroup =  _audioConfiguration.GetByMixerGroup(AudioMixerGroupType.VideoItem);

            SetAudioVolume(AudioMixerGroupType.Master,PlayerPrefs.GetFloat("MasterVolume", 0.5f));
            SetAudioVolume(AudioMixerGroupType.BGMItem,PlayerPrefs.GetFloat("BGMItemVolume", 0.5f));
            SetAudioVolume(AudioMixerGroupType.MusicItem,PlayerPrefs.GetFloat("MusicItemVolume", 0.5f));
            SetAudioVolume(AudioMixerGroupType.HumanItem,PlayerPrefs.GetFloat("HumanItemVolume", 0.5f));
        }

        private async UniTask InitializedMusicSource()
        {
            var source =
                 await AssetsManager.Instance.LoadAssetsUniTask<GameObject>(_audioConfiguration.MusicSourcePath);
            MusicSource = source.GetComponent<AudioSource>();

            GameObject newRoot = new GameObject("AudioPoolRoot");
            newRoot.transform.SetParent(transform);
            newRoot.transform.localPosition = Vector3.zero;

            audioSpawnPool = PoolManager.Pools.Create("AudioManager",newRoot);
            PrefabPool audioPool = new PrefabPool(MusicSource.transform)
            {
                preloadAmount = 20,
            };
            audioSpawnPool.CreatePrefabPool(audioPool);
        }

        private void InitializedSnapshot()
        {
            foreach (var item in _audioConfiguration.MixerSnapshotsList)
            {
                if (!snapshots.ContainsKey(item.Type))
                {
                    snapshots.Add(item.Type, item.Snapshot);
                }
                else
                {
                    Debug.LogWarning("重复快照,将被跳过!");
                }
            }
        }

        public UniTask Release()
        {
            return UniTask.CompletedTask;
        }

        #endregion

        #region Complete

        [ReadOnly,ShowInInspector,BoxGroup("Sources"),LabelText("背景播放器")]
        private AudioSource bgmSource;

        [ReadOnly,ShowInInspector,BoxGroup("Sources"),LabelText("环境播放器")]
        private AudioSource ambientSource;

        [ReadOnly,ShowInInspector,BoxGroup("Sources"),LabelText("人声播放器")]
        private AudioSource humanSource;

        [ReadOnly,ShowInInspector,BoxGroup("Sources"),LabelText("UI播放器")]
        private AudioSource videoSource;

        [ReadOnly,ShowInInspector,BoxGroup("Sources"),LabelText("音效播放器")]
        private AudioSource MusicSource;

        private SpawnPool audioSpawnPool;

        [BoxGroup("Snapshot"),ShowInInspector,ReadOnly,LabelText("快照列表")]
        private Dictionary<AudioSnapshotsType, AudioMixerSnapshot> snapshots = new Dictionary<AudioSnapshotsType, AudioMixerSnapshot>();

        [BoxGroup("Snapshot"),ShowInInspector,LabelText("快照过度时间"),ReadOnly]
        private const float snapshotTimer = 3f;

        [BoxGroup("混音器"),ShowInInspector,LabelText("混音器"),ReadOnly]
        private AudioMixer XMixer;

        #endregion

        #region Play

        /// <summary>
        /// 播放音频
        /// </summary>
        /// <param name="audioID">audio配置表ID</param>
        /// <param name="transitionTime">过度时间</param>
        public void PlayAudio(string audioID,float transitionTime = snapshotTimer)
        {
            if(string.IsNullOrEmpty(audioID))return;
            AudioItemData itemData = _audioConfiguration.GetDataByID(audioID);
            switch (itemData.audioType)
            {
                case AudioType.BGM:
                    PlayBGM(itemData, transitionTime);
                    break;
                case AudioType.Ambient:
                    PlayAmbient(itemData,transitionTime);
                    break;
                case AudioType.Human:
                    PlayHuman(itemData,transitionTime);
                    break;
                case AudioType.Music:
                    PlayMusic(itemData,transitionTime);
                    break;
                case AudioType.Video:
                    PlayVideo(itemData,transitionTime);
                    break;
                default:
                    break;
            }
        }

        /// <summary>
        ///  播放音频
        /// </summary>
        /// <param name="audioPath"> 音频路径</param>
        /// <param name="audioType">音频类型</param>
        /// <param name="transitionTime">过度时间</param>
        public void PlayAudio(string audioPath,AudioType audioType,float transitionTime = snapshotTimer)
        {
            if (string.IsNullOrEmpty(audioPath)) return;
            switch (audioType)
            {
                case AudioType.BGM:
                    PlayBGM(audioPath, transitionTime);
                    break;
                case AudioType.Ambient:
                    PlayAmbient(audioPath, transitionTime);
                    break;
                case AudioType.Human:
                    PlayHuman(audioPath, transitionTime);
                    break;
                case AudioType.Music:
                    PlayMusic(audioPath, transitionTime);
                    break;
                case AudioType.Video:
                    PlayVideo(audioPath, transitionTime);
                    break;
            }
        }

        /// <summary>
        ///  播放音频
        /// </summary>
        /// <param name="clip">音频Clip</param>
        /// <param name="audioType">音频类型</param>
        /// <param name="transitionTime">过度时间</param>
        public void PlayAudio(AudioClip clip,AudioType audioType,float transitionTime = snapshotTimer)
        {
            if (clip == null) return;
            switch (audioType)
            {
                case AudioType.BGM:
                    PlayBGM(clip, transitionTime);
                    break;
                case AudioType.Ambient:
                    PlayAmbient(clip, transitionTime);
                    break;
                case AudioType.Human:
                    PlayHuman(clip, transitionTime);
                    break;
                case AudioType.Music:
                    PlayMusic(clip, transitionTime);
                    break;
                case AudioType.Video:
                    PlayVideo(clip, transitionTime);
                    break;
            }
        }

        public void StopAudio(AudioType audioType)
        {

        }

        #endregion

        #region BGM

        /// <summary>
        /// 播放BGM
        /// </summary>
        /// <param name="itemData">配置数据</param>
        /// <param name="transitionTime">过度时间</param>
        private void PlayBGM(AudioItemData itemData, float transitionTime = snapshotTimer)
        {
            if (itemData == null) return;
            if (itemData.audioClip == null) return;
            PlayBGM(itemData.audioClip, transitionTime);
        }

        /// <summary>
        ///  播放BGM
        /// </summary>
        /// <param name="audioPath">音频路径</param>
        /// <param name="transitionTime">过度时间</param>
        public void PlayBGM(string audioPath, float transitionTime = snapshotTimer)
        {
            if (string.IsNullOrEmpty(audioPath)) return;
            AudioClip clip = AssetsManager.Instance.LoadAssets<AudioClip>(audioPath);
            if (clip == null) return;
            PlayBGM(clip, transitionTime);
        }

        /// <summary>
        ///  播放BGM
        /// </summary>
        /// <param name="clip">音频文件</param>
        /// <param name="transitionTime">过度时间</param>
        public void PlayBGM(AudioClip clip, float transitionTime = snapshotTimer)
        {
            if (clip == null) return;
            if (bgmSource.isActiveAndEnabled)
            {
                bgmSource.clip = clip;
                bgmSource.loop = true;
                bgmSource.Play();
            }
            if (snapshots.ContainsKey(AudioSnapshotsType.Normal))
            {
                snapshots[AudioSnapshotsType.Normal].TransitionTo(transitionTime);
            }
        }


        /// <summary>
        /// 停止播放BGM音效
        /// </summary>
        public void StopBGM()
        {
            bgmSource.Stop();
        }

        #endregion

        #region Ambient

        /// <summary>
        /// 播放环境音
        /// </summary>
        /// <param name="itemData"> 配置数据</param>
        /// <param name="transitionTime"> 过度时间</param>
        private void PlayAmbient(AudioItemData itemData, float transitionTime = snapshotTimer)
        {
            if (itemData == null) return;
            if (itemData.audioClip == null) return;
            PlayAmbient(itemData.audioClip, transitionTime);
        }

        /// <summary>
        ///  播放环境音
        /// </summary>
        /// <param name="audioPath">音频路径</param>
        /// <param name="transitionTime">过度时间</param>
        private void PlayAmbient(string audioPath, float transitionTime = snapshotTimer)
        {
            if (string.IsNullOrEmpty(audioPath)) return;
            AudioClip clip = AssetsManager.Instance.LoadAssets<AudioClip>(audioPath);
            if (clip == null) return;
            PlayAmbient(clip, transitionTime);
        }

        /// <summary>
        ///  播放环境音
        /// </summary>
        /// <param name="clip"> 音频Clip</param>
        /// <param name="transitionTime"> 过度时间</param>
        private void PlayAmbient(AudioClip clip, float transitionTime = snapshotTimer)
        {
            if (clip == null) return;
            if (ambientSource.isActiveAndEnabled)
            {
                ambientSource.clip = clip;
                ambientSource.loop = true;
                ambientSource.Play();
            }
            // if (snapshots.ContainsKey(AudioSnapshotsType.Normal))
            // {
            //     snapshots[AudioSnapshotsType.Normal].TransitionTo(SnapshotTimer);
            // }
        }

        /// <summary>
        /// 停止播放环境音
        /// </summary>
        public void StopAmbient()
        {
            ambientSource.Stop();
        }

        #endregion

        #region Human
        /// <summary>
        ///  播放人声
        /// </summary>
        /// <param name="itemData">配置数据</param>
        /// <param name="transitionTime">过度时间</param>
        private void PlayHuman(AudioItemData itemData, float transitionTime = snapshotTimer)
        {
            if (itemData == null) return;
            if (itemData.audioClip == null) return;
            PlayHuman(itemData.audioClip, transitionTime);
        }

        /// <summary>
        ///  播放人声
        /// </summary>
        /// <param name="audioPath">音频路径</param>
        /// <param name="transitionTime">过度时间</param>
        private void PlayHuman(string audioPath, float transitionTime = snapshotTimer)
        {
            if (string.IsNullOrEmpty(audioPath)) return;
            AudioClip clip = AssetsManager.Instance.LoadAssets<AudioClip>(audioPath);
            if (clip == null) return;
            PlayHuman(clip, transitionTime);
        }

        /// <summary>
        /// 播放人声
        /// </summary>
        /// <param name="clip"> 音频Clip</param>
        /// <param name="transitionTime"> 过度时间</param>
        private void PlayHuman(AudioClip clip, float transitionTime = snapshotTimer)
        {
            if (clip == null) return;
            if (humanSource.isActiveAndEnabled)
            {
                humanSource.clip = clip;
                humanSource.Play();
            }
            if (snapshots.ContainsKey(AudioSnapshotsType.Human))
            {
                snapshots[AudioSnapshotsType.Normal].TransitionTo(transitionTime);
            }
        }

        public void StopHuman()
        {
            humanSource.Stop();
        }
        #endregion

        #region Video

        /// <summary>
        /// 播放视频
        /// </summary>
        /// <param name="itemData"> 配置数据</param>
        /// <param name="transitionTime"> 过度时间</param>
        private void PlayVideo(AudioItemData itemData, float transitionTime = snapshotTimer)
        {
            if (itemData == null) return;
            if (itemData.audioClip == null) return;
            PlayVideo(itemData.audioClip, transitionTime);
        }

        /// <summary>
        /// 播放视频
        /// </summary>
        /// <param name="audioPath">音频路径</param>
        /// <param name="transitionTime">过度时间</param>
        private void PlayVideo(string audioPath, float transitionTime = snapshotTimer)
        {
            if (string.IsNullOrEmpty(audioPath)) return;
            AudioClip clip = AssetsManager.Instance.LoadAssets<AudioClip>(audioPath);
            if (clip == null) return;
            PlayVideo(clip, transitionTime);
        }

        /// <summary>
        /// 播放视频
        /// </summary>
        /// <param name="clip">音频文件</param>
        /// <param name="transitionTime"> 过度时间</param>
        private void PlayVideo(AudioClip clip, float transitionTime = snapshotTimer)
        {
            if (clip == null) return;
            if (videoSource.isActiveAndEnabled)
            {
                videoSource.clip = clip;
                videoSource.Play();
            }

            if (snapshots.ContainsKey(AudioSnapshotsType.Video))
            {
                snapshots[AudioSnapshotsType.Video].TransitionTo(transitionTime);
            }

        }

        public void StopVideo()
        {
            videoSource.Stop();
        }

        #endregion

        #region Music

        private void PlayMusic(AudioItemData itemData,float transitionTime = snapshotTimer)
        {
            if (itemData == null) return;
            if (itemData.audioClip == null) return;
            PlayMusic(itemData.audioClip);
        }

        private void PlayMusic(string audioPath,float transitionTime = snapshotTimer)
        {
            if (string.IsNullOrEmpty(audioPath)) return;
            AudioClip clip = AssetsManager.Instance.LoadAssets<AudioClip>(audioPath);
            if (clip == null) return;
            PlayMusic(clip);
        }

        public void PlayMusic(AudioClip clip,float volume = 1f,Action OnMusicPlayEnd = null)
        { 
            if (clip == null) return;
            Transform temp = audioSpawnPool.Spawn(MusicSource.transform);
            MusicItemSource  musicItemSource = temp.GetComponent<MusicItemSource>();
            musicItemSource.PlayMusic(clip,volume, OnMusicPlayEnd);
        }

        #endregion

        #region Functions

        /// <summary>
        /// 设置音频音量
        /// </summary>
        /// <param name="audioType">音频组类型</param>
        /// <param name="volume">音频组值</param>
        public void SetAudioVolume(AudioMixerGroupType audioType, float volume)
        {
            switch (audioType)
            {
                case AudioMixerGroupType.Master:
                    PlayerPrefs.SetFloat("MasterVolume", volume);
                    SetMixerVolume("MasterVolume", volume);
                    break;
                case AudioMixerGroupType.AmbientMaster:
                    PlayerPrefs.SetFloat("AmbientMasterVolume", volume);
                    SetMixerVolume("AmbientMasterVolume", volume);
                    break;
                case AudioMixerGroupType.AmbientItem:
                    PlayerPrefs.SetFloat("AmbientItemVolume", volume);
                    SetMixerVolume("AmbientItemVolume", volume);
                    break;
                case AudioMixerGroupType.BGMMaster:
                    PlayerPrefs.SetFloat("BGMasterVolume", volume);
                    SetMixerVolume("BGMasterVolume", volume);
                    break;
                case AudioMixerGroupType.BGMItem:
                    PlayerPrefs.SetFloat("BGMItemVolume", volume);
                    SetMixerVolume("BGMItemVolume", volume);
                    break;
                case AudioMixerGroupType.MusicMaster:
                    PlayerPrefs.SetFloat("MusicMasterVolume", volume);
                    SetMixerVolume("MusicMasterVolume", volume);
                    break;
                case AudioMixerGroupType.MusicItem:
                    PlayerPrefs.SetFloat("MusicItemVolume", volume);
                    SetMixerVolume("MusicItemVolume", volume);
                    break;
                case AudioMixerGroupType.HumanMaster:
                    PlayerPrefs.SetFloat("HumanMasterVolume", volume);
                    SetMixerVolume("HumanMasterVolume", volume);
                    break;
                case AudioMixerGroupType.HumanItem:
                    PlayerPrefs.SetFloat("HumanItemVolume", volume);
                    SetMixerVolume("HumanItemVolume", volume);
                    break;
                case AudioMixerGroupType.VideoMaster:
                    PlayerPrefs.SetFloat("VideoMasterVolume", volume);
                    SetMixerVolume("VideoMasterVolume", volume);
                    break;
                case AudioMixerGroupType.VideoItem:
                    PlayerPrefs.SetFloat("VideoItemVolume", volume);
                    SetMixerVolume("VideoItemVolume", volume);
                    break;
                default:
                    break;
            }
        }

        /// <summary>
        /// 设置混合器音量
        /// </summary>
        private void SetMixerVolume(string mixerName, float value)
        {
            XMixer.SetFloat(mixerName, ConvertMixerVolume(value));
        }

        /// <summary>
        /// 将0~1的音效转换为音阶值
        /// </summary>
        /// <param name="amount"></param>
        /// <returns></returns>
        private float ConvertMixerVolume(float amount)
        {
            return (amount * 100 - 80);
        }

        #endregion

        #region Tools

        /// <summary>
        /// 获取对应类型的混合器组件
        /// </summary>
        /// <param name="type"></param>
        /// <returns></returns>
        public AudioMixerGroup GetTypeMixerGroup(AudioMixerGroupType type)
        {
            return _audioConfiguration.GetByMixerGroup(type);
        }

        #endregion

    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Cysharp.Threading.Tasks;
using Newtonsoft.Json;
using Sirenix.OdinInspector;
using UnityEngine;

namespace XFramework
{
    /// <summary>
    /// 游戏存储管理器
    /// </summary>
    public class SaveGameManager : MonoSingleton<SaveGameManager>,IGameInitialized
    {
        #region Config
        /// <summary>
        /// 缓存存储Json文件的位置
        /// </summary>
        private static string JsonSavePath;

        /// <summary>
        /// 存档子目录名（保持原值，勿改，否则旧存档会失效）
        /// </summary>
        private const string SaveFolderName = "GameSaveData";

        /// <summary>存档目录绝对路径</summary>
        private static string SaveDir => Path.Combine(JsonSavePath, SaveFolderName);

        /// <summary>某个用户存档文件路径</summary>
        private static string GetUserPath(int userID) => Path.Combine(SaveDir, $"User{userID}.scriptable");

        /// <summary>用户列表文件路径</summary>
        private static string UsersPath => Path.Combine(SaveDir, "Logic.scriptable");

        /// <summary>确保存档目录存在</summary>
        private static void EnsureSaveDir()
        {
            if (!Directory.Exists(SaveDir))
                Directory.CreateDirectory(SaveDir);
        }
        #endregion
        /// <summary>
        /// 存档下所有的用户列表
        /// </summary>
        public List<UserSaveSummary> Users { get; private set; }
        private List<ISaveable> iSaveables = new();
        /// <summary>
        /// 当前用户对象
        /// </summary>
        public UserSaveSummary CurUserSaveSummary { get; private set; }

        [SerializeReference] GameSaveData curGameSaveData;

        /// <summary>
        /// 注册函数将自身要存储的信息注册到ISaveablesList中
        /// </summary>
        /// <param name="saveable"></param>
        public void RegisterSaveable(ISaveable saveable)
        {
            if (!iSaveables.Contains(saveable))
            {
                iSaveables.Add(saveable);
            }
        }
        public void RemoveSaveable(ISaveable saveable)
        {
            iSaveables.Remove(saveable);
        }

        #region 保存用户数据

        public void Save()
        {
            Save(CurUserSaveSummary);
        }

        /// <summary>
        /// 保存用户数据
        /// </summary>
        /// <param name="userSaveSummary">用户</param>
        private void Save(UserSaveSummary userSaveSummary)
        {
            if (userSaveSummary == null)
            {
                Debug.LogError("保存存档失败：userSaveSummary == null");
                return;
            }
            if (curGameSaveData == null)
            {
                Debug.LogError("保存存档失败：gameSaveData == null，请先 Load / CreateUser 后再保存");
                return;
            }

            RefreshUserSummary(userSaveSummary);
            foreach (var SaveItem in iSaveables)
            {
                SaveItem.SaveData(curGameSaveData);
            }

            var path = GetUserPath(userSaveSummary.UserID);
            try
            {
                EnsureSaveDir();
                var JsonData = JsonConvert.SerializeObject(curGameSaveData, Formatting.Indented);
                File.WriteAllText(path, JsonData);
            }
            catch (Exception e)
            {
                Debug.LogError($"保存存档写入文件失败 path={path}\n{e}");
                return;
            }

            SaveUsers();
        }

        #endregion

        #region 加载用户数据
        /// <summary>
        /// 加载用户数据
        /// </summary>
        /// <param name="userSaveSummary">用户</param>
        public void Load(UserSaveSummary userSaveSummary)
        {
            CurUserSaveSummary = userSaveSummary;
            string path = GetUserPath(userSaveSummary.UserID);

            curGameSaveData = LoadGameSaveData(path);

            foreach (ISaveable item in iSaveables)
                item.LoadData(curGameSaveData);
        }

        /// <summary>
        /// 读取存档文件并反序列化；文件不存在 / 读取失败 / 坏档时回退到新存档。
        /// </summary>
        private static GameSaveData LoadGameSaveData(string path)
        {
            if (!File.Exists(path))
                return GameSaveData.Create();

            try
            {
                var json = File.ReadAllText(path);
                return JsonConvert.DeserializeObject<GameSaveData>(json) ?? GameSaveData.Create();
            }
            catch (Exception e)
            {
                Debug.LogError($"读取存档失败（文件可能已损坏），将回退到新存档 path={path}\n{e}");
                return GameSaveData.Create();
            }
        }

        /// <summary>
        /// 删除用户数据
        /// </summary>
        /// <param name="UID"></param>
        public void Delete(int UID)
        {
            var path = GetUserPath(UID);
            try
            {
                if (File.Exists(path))
                    File.Delete(path);
            }
            catch (Exception e)
            {
                Debug.LogError($"删除存档文件失败 path={path}\n{e}");
            }
        }


        #endregion

        #region 保存用户

        /// <summary>
        /// 保存所有用户
        /// </summary>
        private void SaveUsers()
        {
            try
            {
                EnsureSaveDir();
                var JsonData = JsonConvert.SerializeObject(Users, Formatting.Indented);
                File.WriteAllText(UsersPath, JsonData);
            }
            catch (Exception e)
            {
                Debug.LogError($"保存用户列表失败 path={UsersPath}\n{e}");
            }
        }

        #endregion

        #region 加载用户

        /// <summary>
        /// 加载所有用户
        /// </summary>
        private void LoadUsers()
        {
            List<UserSaveSummary> slotData = null;
            if (File.Exists(UsersPath))
            {
                try
                {
                    var JsonData = File.ReadAllText(UsersPath);
                    slotData = JsonConvert.DeserializeObject<List<UserSaveSummary>>(JsonData);
                }
                catch (Exception e)
                {
                    Debug.LogError($"读取用户列表失败（文件可能已损坏），将按空列表处理 path={UsersPath}\n{e}");
                }
            }

            Users = slotData is { Count: > 0 } ? slotData : new List<UserSaveSummary>();
            UsersChangeAction?.Invoke(Users);
        }

        #endregion

        #region 增加用户


        public void CreateUser(int idx, string UserName)
        {
            UserSaveSummary newUserSaveSummary = new()
            {
                UserID = idx,
                UserName = UserName,
                CreateTime = DateTime.Now,
                PreviewGoldNumber = GameDataManager.Instance.GameSettingsData.StarGoldNumber,
                PreviewDay = 1,
                PreviewWeek = 1,
            };

            int index = Users.FindIndex(temp => temp.UserID == idx);
            if (index >= 0)
                Users[index] = newUserSaveSummary;
            else
                Users.Add(newUserSaveSummary);

            // 新档：用 Create() 生成默认存档下发给各管理器，再落盘
            CurUserSaveSummary = newUserSaveSummary;
            curGameSaveData = GameSaveData.Create();
            foreach (var saveItem in iSaveables)
                saveItem.LoadData(curGameSaveData);

            Save(newUserSaveSummary);
            LoadUsers();
            GameManager.Instance.EnterGame(newUserSaveSummary);
        }

        public void SaveUser(int idx, UserSaveSummary newUserSaveSummary)
        {
            if (newUserSaveSummary == null)
            {
                Debug.LogError("SaveUser 失败：newUserSaveSummary == null");
                return;
            }

            // 另存到「其它」槽位时克隆一份，避免就地篡改原槽位摘要的引用（否则会串档/产生重复条目）；
            // 存到「同一」槽位时直接复用本体。
            var summary = newUserSaveSummary.UserID == idx ? newUserSaveSummary : newUserSaveSummary.Clone();
            summary.UserID = idx;

            int index = Users.FindIndex(temp => temp.UserID == idx);
            if (index >= 0)
                Users[index] = summary;
            else
                Users.Add(summary);

            // 当前游戏现在归属到该槽位，后续 Save() 也写入此槽位
            CurUserSaveSummary = summary;

            // Save() 内部已写入存档文件并调用 SaveUsers()，此处无需重复保存用户列表
            Save(summary);
        }

        /// <summary>
        /// 删除一个已有存档
        /// </summary>
        /// <param name="UID">已有存档的用户唯一标识UID</param>
        public void DeleteUser(int UID)
        {
            int index = Users.FindIndex(temp => temp.UserID == UID);
            if (index >= 0)
            {
                Delete(Users[index].UserID);
                Users.RemoveAt(index);
                SaveUsers();
                UsersChangeAction?.Invoke(Users);
            }
        }

        #endregion

        #region Enven 事件回调函数

        private Action<List<UserSaveSummary>> UsersChangeAction;

        /// <summary>
        /// 注册所有用户变化回调
        /// </summary>
        /// <param name="callBack"></param>
        public void RegisterUsersChange(Action<List<UserSaveSummary>> callBack)
        {
            UsersChangeAction += callBack;
            callBack?.Invoke(Users);
        }

        /// <summary>
        /// 反注册所有用户变化回调
        /// </summary>
        /// <param name="callBack"></param>
        public void UnregisterUsersChange(Action<List<UserSaveSummary>> callBack)
        {
            UsersChangeAction -= callBack;
        }

        #endregion

        #region 摘要同步

        private void RefreshUserSummary(UserSaveSummary summary)
        {
            if (summary == null)
                return;

            PlayerData playerData = GameDataManager.Instance.PlayerData;

            if (playerData == null)
            {
                Debug.LogWarning("刷新存档摘要失败：PlayerData == null");
                return;
            }

            summary.UserName = playerData.UserName;
            summary.PreviewGoldNumber = playerData.GetProperty(PropertyType.Gold);
            summary.PreviewDay = playerData.Day;
            summary.PreviewWeek = playerData.Week;

            int index = Users.FindIndex(temp => temp.UserID == summary.UserID);

            if (index >= 0)
            {
                Users[index] = summary;
            }
            else
            {
                Users.Add(summary);
            }
        }

        #endregion

        /// <summary>
        /// 初始化脚本函数
        /// </summary>
        /// <returns></returns>
        public async UniTask Initialized()
        {
            JsonSavePath = Application.persistentDataPath;
            LoadUsers();
            await UniTask.CompletedTask;
        }

        /// <summary>
        /// 释放脚本函数
        /// </summary>
        public async UniTask Release()
        {
            await UniTask.CompletedTask;
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Cysharp.Threading.Tasks;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.SceneManagement;
using Object = UnityEngine.Object;

namespace XFramework
{
    /// <summary>
    /// 编辑器下资源加载模式。
    /// LocalAssetDatabase 用 AssetDatabase/EditorSceneManager 直接读本地资源，速度快，适合日常开发。
    /// Addressables 使用真实 Addressables 加载链路，适合验证分组、Key、依赖、远程包和发布环境问题。
    /// </summary>
    public enum AssetsLoadMode
    {
        LocalAssetDatabase,
        Addressables,
    }

    /// <summary>
    /// 数据加载完成后的回调委托
    /// </summary>
    /// <typeparam name="T"></typeparam>
    public delegate void LoadCallBack<in T>(T t);

    /// <summary>
    /// 全局单例资源管理器
    /// </summary>
    public class AssetsManager : Singleton<AssetsManager>
    {
        #region LoadMode

#if UNITY_EDITOR
        private AssetsLoadMode _loadMode = AssetsLoadMode.LocalAssetDatabase;
#else
        private AssetsLoadMode _loadMode = AssetsLoadMode.Addressables;
#endif

        /// <summary>
        /// 当前资源加载模式。打包后始终会使用 Addressables。
        /// </summary>
        public AssetsLoadMode LoadMode => _loadMode;

        /// <summary>
        /// 编辑器下是否使用本地 AssetDatabase/EditorSceneManager 加载。
        /// </summary>
        public bool UseLocalAssetDatabase
        {
            get
            {
#if UNITY_EDITOR
                return _loadMode == AssetsLoadMode.LocalAssetDatabase;
#else
                return false;
#endif
            }
        }

        /// <summary>
        /// 设置资源加载模式。建议在任何资源加载前设置，避免已有缓存和新模式混用。
        /// </summary>
        public void SetLoadMode(AssetsLoadMode loadMode)
        {
#if UNITY_EDITOR
            if (_loadMode == loadMode)
            {
                return;
            }

            if (HasLoadedCache())
            {
                Debug.LogWarning("切换 AssetsManager 加载模式时已有资源缓存，建议重新进入 Play 或在游戏初始化前设置，避免本地资源和 Addressables 资源混用。");
            }

            _loadMode = loadMode;
#else
            _loadMode = AssetsLoadMode.Addressables;
#endif
        }

        private bool HasLoadedCache()
        {
            return pools.Count > 0
                   || lookup.Count > 0
                   || AssetsDic.Count > 0
                   || SceneDic.Count > 0
                   || AssetReferenceDic.Count > 0;
        }

        #endregion

        #region UnitygGameObject
        /// <summary>
        /// 缓存对象的跟节点
        /// </summary>
        public Transform PoolRoot;
        /// <summary>
        /// GameObjectLoader 对象池
        /// </summary>
        private Dictionary<string, GameObjectLoader> pools = new Dictionary<string, GameObjectLoader>();
        /// <summary>
        /// 缓存查找表
        /// </summary>
        private Dictionary<GameObject, GameObjectLoader> lookup = new Dictionary<GameObject, GameObjectLoader>();
        public AssetsManager()
        {
            UnityEngine.Transform poolNode = new GameObject("[Asset Pool]").transform;
            poolNode.transform.localPosition = Vector3.zero;
            poolNode.transform.localScale = Vector3.one;
            poolNode.transform.localRotation = Quaternion.identity;
            Object.DontDestroyOnLoad(poolNode);
            PoolRoot = poolNode;
            //TODO: 开启定时器,定时清理缓存
        }
        /// <summary>
        /// 定时清理缓存
        /// </summary>
        public void UpdateTimeReleaseAll()
        {
            foreach (var item in this.pools.Values)
            {
                item.Release();
            }
        }
        /// <summary>
        /// 同步实例化GameObject
        /// </summary>
        /// <param name="key">键</param>
        /// <returns></returns>
        public GameObject Instantiate(string key)
        {
            GameObjectLoader loader;
            if (this.pools.TryGetValue(key, out loader)) //如果对象池中有该对象
            {
                var obj = loader.Instantiate();
                this.lookup.Add(obj,loader);
                return obj;
            }
            else //如果池中没有该对象,则实例化后放入池中
            {
                loader = new GameObjectLoader(key);
                var obj = loader.Instantiate();
                this.pools.Add(key,loader);
                this.lookup.Add(obj,loader);
                return obj;
            }
        }
        /// <summary>
        /// 异步实例化GameObject
        /// </summary>
        /// <param name="key">键</param>
        /// <param name="OnComponet">回调函数</param>
        public void InstantiateAsync(string key, LoadCallBack<GameObject> OnComponet)
        {
            GameObjectLoader loader;
            if (this.pools.TryGetValue(key, out loader)) //如果对象池中有该对象
            {
                var obj = loader.Instantiate();
                this.lookup.Add(obj,loader);
            }
            else //如果池中没有该对象,则实例化后放入池中
            {
                loader = new GameObjectLoader(key);
                loader.InstantiateAsync((OBJGame) =>
                {
                    this.pools.Add(key,loader);
                    this.lookup.Add(OBJGame,loader);
                    OnComponet?.Invoke(OBJGame);
                });

            }
        }
        /// <summary>
        /// 获取预制体对象
        /// </summary>
        /// <param name="key"></param>
        /// <returns></returns>
        public GameObject GetTemplate(string key)
        {
            if (this.pools.TryGetValue(key, out var loader))
            {
                return loader.prefab;
            }
            return null;
        }
        /// <summary>
        /// 将资源释放回缓存池
        /// </summary>
        /// <param name="obj"></param>
        public void FreeGameObject(GameObject obj)
        {
            GameObjectLoader loader;
            if (lookup.TryGetValue(obj, out loader))
            {
                loader.Free(obj);
                lookup.Remove(obj);
            }
        }

        public void RemovePools(string key)
        {
            if (pools.ContainsKey(key))
            {
                pools.Remove(key);
            }
        }

        #endregion

        #region AssetsLoader

        private Dictionary<string, AssetsLoader> AssetsDic = new Dictionary<string, AssetsLoader>();


        /// <summary>
        /// 同步加载资源
        /// </summary>
        /// <param name="key">键</param>
        /// <typeparam name="T">类型</typeparam>
        /// <returns></returns>
        public T LoadAssets<T>(string key) where T : Object
        {
            AssetsLoader loader;
            if (AssetsDic.TryGetValue(key, out loader))
            {
                T Assets = loader.LoadAsset<T>();
                return Assets;
            }
            else
            {
                loader = new AssetsLoader(key);
                T Assets = loader.LoadAsset<T>();
                AssetsDic.Add(key,loader);
                return Assets;
            }
        }

        /// <summary>
        /// UniTask 异步加载资源
        /// </summary>
        /// <param name="key"></param>
        /// <typeparam name="T"></typeparam>
        /// <returns></returns>
        public UniTask<T> LoadAssetsUniTask<T>(string key) where T : Object
        {
            AssetsLoader loader;
            if (AssetsDic.TryGetValue(key, out loader))
            {
                return loader.LoadAssetUniTask<T>();
            }
            else
            {
                loader = new AssetsLoader(key);
                UniTask<T> Assets = loader.LoadAssetUniTask<T>();
                AssetsDic.Add(key,loader);
                return Assets;
            }
        }

        /// <summary>
        /// 异步加载资源
        /// </summary>
        /// <param name="key">键</param>
        /// <param name="OnComplete">回调函数</param>
        /// <typeparam name="T"></typeparam>
        public void LoadAssetsAsync<T>(string key,LoadCallBack<T> OnComplete) where T : Object
        {
            AssetsLoader loader;
            if (AssetsDic.TryGetValue(key, out loader))
            {
                loader.LoadAssetAsync(OnComplete);
            }
            else
            {
                loader = new AssetsLoader(key);
                loader.LoadAssetAsync<T>((t) =>
                {
                    OnComplete?.Invoke(t);
                });
                AssetsDic.Add(key,loader);
            }
        }

        /// <summary>
        /// Task异步加载资源
        /// </summary>
        /// <param name="key"></param>
        /// <typeparam name="T"></typeparam>
        /// <returns></returns>
        public Task<T> LoadAssetTask<T>(string key) where T : Object
        {
            AssetsLoader loader;
            if (AssetsDic.TryGetValue(key, out loader))
            {
                return loader.LoadAssetTask<T>();
            }
            loader = new AssetsLoader(key);
            AssetsDic.Add(key,loader);
            return loader.LoadAssetTask<T>();//??
        }

        /// <summary>
        /// 携程加载资源
        /// </summary>
        /// <param name="key">Addressable Key键</param>
        /// <param name="OnComplete">加载完成后的回调</param>
        /// <typeparam name="T"></typeparam>
        /// <returns></returns>
        public IEnumerator LoadAssetsCoroutine<T>(string key, LoadCallBack<T> OnComplete) where T : Object
        {
            AssetsLoader loader;
            if (AssetsDic.TryGetValue(key, out loader))
            {
                yield return loader.LoadAssetCoroutine(OnComplete);
            }
            else
            {
                loader = new AssetsLoader(key);
                yield return loader.LoadAssetCoroutine(OnComplete);
                AssetsDic.Add(key, loader);
            }
        }

        /// <summary>
        /// 释放资源
        /// </summary>
        /// <param name="key"></param>
        public void FreeAsset(string key)
        {
            AssetsLoader loader;
            if (AssetsDic.TryGetValue(key,out loader))
            {
                loader.Free();
            }
        }



        /// <summary>
        /// 释放 AssetReference 资源
        /// </summary>
        public void FreeAsset(AssetReference assetReference)
        {
            if (assetReference == null)
            {
                return;
            }

            var key = GetAssetReferenceKey(assetReference);
            AssetReferenceLoader loader;
            if (AssetReferenceDic.TryGetValue(key, out loader))
            {
                loader.Free();
            }
        }
        /// <summary>
        /// 资源池移除对象
        /// </summary>
        /// <param name="key"></param>
        public void RemoveAssetsDic(string key)
        {
            if (AssetsDic.ContainsKey(key))
            {
                AssetsDic.Remove(key);
            }
        }

        public void FreeAssets()
        {
            for (int i = 0; i < AssetsDic.Count; i++)
            {
                (string key, AssetsLoader loader) = AssetsDic.ElementAt(i);
                loader.Release();
            }
            AssetsDic.Clear();
        }

        internal void RemoveAssetReferenceDic(string key)
        {
            if (AssetReferenceDic.ContainsKey(key))
            {
                AssetReferenceDic.Remove(key);
            }
        }

        #endregion

        #region SceneLoader

        private Dictionary<string, SceneLoader> SceneDic = new Dictionary<string, SceneLoader>();

